<div><div class="flex items-center justify-between mb-4"><h3 class="font-medium">Members (<span x-text="members.length+'/'+maxMembers"></span>)</h3><x-capstone::button size="sm" x-show="actions.can_add_member" @click="openMember()"><x-capstone::icon name="UserPlus" />Add Member</x-capstone::button></div><div class="space-y-2"><template x-for="member in members" :key="member.id"><div class="flex items-center justify-between p-3 border rounded-lg gap-2"><div class="flex items-center gap-3 min-w-0"><div class="h-8 w-8 shrink-0 rounded-full bg-primary/10 flex items-center justify-center"><x-capstone::icon name="Users" class="h-4 w-4 text-primary" /></div><div class="min-w-0"><p class="font-medium truncate" x-text="person(member.student)"></p><p class="text-sm text-muted-foreground truncate" x-text="email(member.student)"></p></div><x-capstone::badge variant="secondary" x-show="member.is_leader">Leader</x-capstone::badge></div><x-capstone::button variant="ghost" size="sm" aria-label="Remove member" x-show="actions.can_remove_member && !member.is_leader" @click="confirm('remove',member)"><x-capstone::icon name="X" class="text-destructive" /></x-capstone::button></div></template></div></div>
